<?php require __DIR__.'/../inc/auth.php'; require __DIR__.'/../inc/layout.php'; need_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){
  $type=$_POST['type']; $from=$_POST['from']?:'2000-01-01'; $to=$_POST['to']?:'2999-12-31';
