        'Tasks'=>["SELECT f.name field,t.fertilizer,t.app_date,t.app_time,t.qty,t.priority,t.status FROM tasks t JOIN fields f ON f.id=t.field_id WHERE t.app_date BETWEEN ? AND ?",[$from,$to]],
        'Production'=>["SELECT f.name field,p.month_date,p.tons FROM production p JOIN fields f ON f.id=p.field_id WHERE p.month_date BETWEEN ? AND ?",[$from,$to]],
        'Users'=>["SELECT name,email,role,status FROM users"]];
  $d=rows($map[$type][0],$map[$type][1]??[]);
  q("INSERT INTO reports(name,type,generated_by) VALUES(?,?,?)",[$type.' Report '.date('Y-m-d H:i'),$type,$_SESSION['user']['id']]); log_act("Report generated: $type");
  header('Content-Type: text/csv'); header('Content-Disposition: attachment; filename="optifarm_'.strtolower($type).'_'.date('Ymd').'.csv"');
  $o=fopen('php://output','w'); if($d){fputcsv($o,array_keys($d[0])); foreach($d as $r)fputcsv($o,$r);} exit;
}
$ft=$_GET['type']??''; $list=rows("SELECT r.*,u.name uname FROM reports r LEFT JOIN users u ON u.id=r.generated_by WHERE (?='' OR r.type=?) ORDER BY r.id DESC",[$ft,$ft]);
